    const row=await env.DB.prepare('SELECT (SELECT COUNT(*) FROM search_usage WHERE month = ?1) AS monthly, (SELECT COUNT(*) FROM search_usage WHERE day = ?2 AND user_id = ?3) AS daily').bind(month,day,user).first();
